create table lorasens_lwg_shelves_config (
    device_id uuid not null references devices,
    weight_g_param_id text not null,
    item_weight_g integer not null, -- items = weight / item_weight_g
    fixed_tare_weight_g integer, -- weight = weight - fixed_tare_weight_g
    stacked_tare_weight_g integer, -- weight = weight % (stacked_tare_weight_g +
    stacked_tare_items_max integer, --                   item_weight_g*stacked_tare_items_max)
    primary key (device_id, weight_g_param_id)
);
